// client/src/pages/CouponCenter.jsx

import React, { useEffect, useState } from 'react';
// 🚨 이전 에러 수정: fetchMyCoupons -> getMyCoupons 로 변경
// redeemCoupon은 이미 존재한다고 가정하고 그대로 둡니다.
import { getMyCoupons, redeemCoupon } from '../api/couponApi'; 

function CouponCenter() {
  const [coupons, setCoupons] = useState([]);

  useEffect(() => {
    const load = async () => {
      try {
        // 🚨 함수 이름 수정: fetchMyCoupons -> getMyCoupons
        const res = await getMyCoupons();
        
        // 💡 서버 응답 구조를 예상하여 수정: 
        // 일반적으로 목록 응답은 res.data.coupons 또는 res.data 자체를 배열로 가정합니다.
        // 여기서는 res.data가 바로 배열이라고 가정하고 진행합니다. (필요시 res.data.coupons로 변경 가능)
        setCoupons(res || []); 
      } catch (err) {
        console.error('load coupons', err);
        // 사용자에게 오류 알림 (선택 사항)
        alert('쿠폰 목록을 불러오는 데 실패했습니다.');
      }
    };
    load();
  }, []);

  const handleCopy = (code) => {
    navigator.clipboard.writeText(code);
    alert('쿠폰 코드가 복사되었습니다.');
  };

  const handleRedeem = async (id) => {
    try {
      const res = await redeemCoupon(id);
      alert('쿠폰 사용 완료!');
      
      // 💡 상태 업데이트: 서버가 사용 완료된 쿠폰 정보를 응답으로 보내주었다고 가정
      // res.data에 사용 처리된 쿠폰 객체가 들어있다고 가정합니다.
      setCoupons(prevCoupons => 
        prevCoupons.map(c => (c._id === id ? res.data : c)) // 서버가 응답으로 준 객체(res.data)로 대체
      );
    } catch (err) {
      alert('사용 실패: ' + (err.response?.data?.message || err.message));
    }
  };

  return (
    <div style={{ padding: 20 }}>
      <h2>내 쿠폰</h2>

      {coupons.length === 0 && <p>아직 쿠폰이 없습니다.</p>}

      {coupons.map(coupon => (
        <div key={coupon._id} style={{ padding: 12, border: '1px solid #ddd', marginBottom: 8, borderRadius: 8 }}>
          {/* 💡 쿠폰 데이터 필드: brand, discount, code, externalUrl, redeemed 사용 */}
          <div>
            <strong>{coupon.brand}</strong> — {coupon.discount}% 할인
          </div>
          <div style={{ marginTop: 6 }}>코드: <strong>{coupon.code}</strong></div>

          {coupon.externalUrl && (
            <button
              style={{ marginTop: 6 }}
              onClick={() => {
                handleCopy(coupon.code); // 코드 복사도 함께 하도록 UX 개선
                window.open(coupon.externalUrl, '_blank');
              }}
            >
              사용처 이동 (코드 자동 복사)
            </button>
          )}

          {/* 코드 복사 버튼은 사용처 이동 버튼에 통합하거나 독립적으로 유지 가능 */}
          {/* <button style={{ marginLeft: 8 }} onClick={() => handleCopy(coupon.code)}>
            코드 복사
          </button> */}

          {!coupon.redeemed && (
            <button style={{ marginLeft: 8 }} onClick={() => handleRedeem(coupon._id)}>
              쿠폰 사용 처리
            </button>
          )}

          {coupon.redeemed && <span style={{ marginLeft: 8, color: 'green' }}>✓ 사용 완료</span>}
        </div>
      ))}
    </div>
  );
}

export default CouponCenter;
